-- ════════════════════════════════════════════════════════════
-- READ-ONLY with respect to persistent data: creates TEMP tables only
-- (session-local, disappear when the session ends). Does not depend on
-- migration v5 objects, so it can run BEFORE the migration.
--
-- Category per (student, month, currency):
--   A  verified for automatic recovery
--   B  needs human review — NEVER recovered automatically
--   C  no correction needed
-- ════════════════════════════════════════════════════════════

DROP TABLE IF EXISTS pg_temp.recon_params, pg_temp.recon_months, pg_temp.recon_people,
                     pg_temp.recon_tx, pg_temp.recon_rows, pg_temp.recon_facts,
                     pg_temp.recon_result, pg_temp.recon_plan, pg_temp.recon_start_date;

CREATE TEMP TABLE recon_params AS
SELECT
  date '2026-08-01' AS from_month,
  date '2026-10-01' AS to_month,
  -- AUTO_CREDIT_RANKS:BEGIN
  ARRAY['אשראי', 'בנקאי', 'קירוב לבבות', 'מרכז הצדקה']::text[]
  -- AUTO_CREDIT_RANKS:END
    AS auto_ranks,
  -- ranks that the ORIGINAL repo function credited — used only to explain anomalies
  ARRAY['אשראי', 'בנקאי', 'א"א']::text[] AS legacy_ranks,
  now() AS generated_at;

CREATE TEMP TABLE recon_months AS
SELECT gs::date AS month
FROM recon_params p, generate_series(p.from_month, p.to_month, interval '1 month') gs;

-- ── people: current students + alumni (same UUID after graduation) ──────────
CREATE TEMP TABLE recon_people AS
SELECT
  s.id                                                         AS student_id,
  'student'::text                                              AS person_kind,
  trim(coalesce(s.last_name, '') || ' ' || coalesce(s.first_name, '')) AS name,
  s.class_name,
  s.passport_or_id,
  CASE WHEN trim(s.tuition) ~ '^[0-9]+(\.[0-9]+)?$' THEN trim(s.tuition)::numeric END AS cur_amount,
  s.tuition                                                    AS cur_tuition_raw,
  s.tuition_currency                                           AS cur_currency,
  nullif(trim(s.tuition_rank), '')                             AS cur_rank,
  CASE WHEN s.tuition_start_date::text ~ '^\d{4}-\d{2}-\d{2}$'
       THEN s.tuition_start_date::text::date END               AS start_date,
  s.created_at,
  s.updated_at,
  NULL::timestamptz                                            AS graduated_at
FROM public.students s
UNION ALL
SELECT
  a.id, 'alumni',
  trim(coalesce(a.last_name, '') || ' ' || coalesce(a.first_name, '')),
  a.class_name, a.passport_or_id,
  CASE WHEN trim(a.tuition) ~ '^[0-9]+(\.[0-9]+)?$' THEN trim(a.tuition)::numeric END,
  a.tuition, a.tuition_currency, nullif(trim(a.tuition_rank), ''),
  CASE WHEN a.tuition_start_date::text ~ '^\d{4}-\d{2}-\d{2}$'
       THEN a.tuition_start_date::text::date END,
  a.created_at, a.updated_at, a.graduated_at
FROM public.alumni a
WHERE NOT EXISTS (SELECT 1 FROM public.students s WHERE s.id = a.id);

CREATE UNIQUE INDEX ON recon_people(student_id);

-- ── all transactions (active + cancelled), classified ──────────────────────
CREATE TEMP TABLE recon_tx AS
SELECT
  t.id, t.student_id, t.billing_month, t.transaction_date, t.amount, t.currency,
  t.transaction_type, t.source, t.note, t.created_at, t.created_by, t.cancelled_at,
  (t.cancelled_at IS NULL)                                                   AS is_active,
  (t.transaction_type = 'monthly_charge'    AND t.source = 'automatic')      AS is_auto_charge,
  (t.transaction_type = 'automatic_payment' AND t.source = 'automatic')      AS is_auto_credit,
  (t.transaction_type = 'manual_charge' OR (t.transaction_type = 'adjustment' AND t.amount < 0)
   OR (t.transaction_type = 'monthly_charge' AND t.source <> 'automatic'))   AS is_manual_debit,
  (t.transaction_type = 'manual_payment' OR (t.transaction_type = 'adjustment' AND t.amount > 0)
   OR (t.transaction_type = 'automatic_payment' AND t.source <> 'automatic')) AS is_manual_credit,
  (t.transaction_type NOT IN ('monthly_charge','automatic_payment','manual_charge','manual_payment','adjustment'))
                                                                             AS is_unknown_type
FROM public.tuition_transactions t;

CREATE INDEX ON recon_tx(student_id, billing_month);

-- ── rows: (student, month, currency) ────────────────────────────────────────
-- Students considered: anyone with a transaction in the window (±1 month),
-- plus every current student with a valid tuition amount and currency.
-- Currency of a row = currency of existing tx in that month, else the
-- expected currency (adjacent automatic charge → current currency).
CREATE TEMP TABLE recon_rows AS
WITH params AS (SELECT * FROM recon_params),
pop AS (
  SELECT DISTINCT t.student_id
  FROM recon_tx t, params p
  WHERE t.billing_month BETWEEN (p.from_month - interval '1 month') AND (p.to_month + interval '1 month')
  UNION
  SELECT pe.student_id FROM recon_people pe
  WHERE pe.person_kind = 'student' AND pe.cur_amount > 0 AND pe.cur_currency IN ('ILS', 'USD')
  UNION
  -- tuition text the cron cannot parse (e.g. '1,400') — silently skipped by the cron
  SELECT pe.student_id FROM recon_people pe
  WHERE pe.person_kind = 'student' AND pe.cur_amount IS NULL
    AND nullif(trim(pe.cur_tuition_raw), '') IS NOT NULL
),
grid AS (SELECT pop.student_id, m.month FROM pop CROSS JOIN recon_months m),
expected AS (
  SELECT g.student_id, g.month,
    coalesce(
      (SELECT t.currency FROM recon_tx t WHERE t.student_id = g.student_id AND t.billing_month = g.month
         AND t.is_auto_charge ORDER BY t.is_active DESC, t.created_at LIMIT 1),
      (SELECT t.currency FROM recon_tx t WHERE t.student_id = g.student_id
         AND t.billing_month = (g.month - interval '1 month')::date AND t.is_auto_charge AND t.is_active LIMIT 1),
      (SELECT t.currency FROM recon_tx t WHERE t.student_id = g.student_id
         AND t.billing_month = (g.month + interval '1 month')::date AND t.is_auto_charge AND t.is_active LIMIT 1),
      (SELECT pe.cur_currency FROM recon_people pe WHERE pe.student_id = g.student_id
         AND pe.cur_currency IN ('ILS', 'USD'))
    ) AS currency
  FROM grid g
)
SELECT student_id, month, currency, true AS is_expected_currency FROM expected WHERE currency IS NOT NULL
UNION
SELECT t.student_id, t.billing_month, t.currency, false
FROM recon_tx t
JOIN recon_months m ON m.month = t.billing_month
WHERE NOT EXISTS (SELECT 1 FROM expected e WHERE e.student_id = t.student_id
                    AND e.month = t.billing_month AND e.currency = t.currency)
UNION
-- expected currency unknown and no tx: still surface the row (as B)
SELECT e.student_id, e.month, NULL, true FROM expected e
WHERE e.currency IS NULL
  AND NOT EXISTS (SELECT 1 FROM recon_tx t WHERE t.student_id = e.student_id AND t.billing_month = e.month);

-- ── facts per row ───────────────────────────────────────────────────────────
CREATE TEMP TABLE recon_facts AS
SELECT
  r.student_id, r.month, r.currency, r.is_expected_currency,
  pe.person_kind, pe.name, pe.class_name, pe.passport_or_id, pe.cur_amount, pe.cur_tuition_raw,
  pe.cur_currency, pe.cur_rank, pe.start_date, pe.updated_at, pe.graduated_at,
  (pe.cur_rank = ANY (p.auto_ranks))                                         AS rank_approved_now,
  -- this month, this currency
  ac.id AS auto_charge_id, ac.amount AS auto_charge_amount, ac.n AS auto_charge_count,
  EXISTS (SELECT 1 FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
            AND t.is_auto_charge AND NOT t.is_active)                       AS auto_charge_cancelled,
  acr.amount AS auto_credit_amount, acr.n AS auto_credit_count,
  EXISTS (SELECT 1 FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
            AND t.is_auto_credit AND NOT t.is_active)                       AS auto_credit_cancelled,
  -- any auto charge/credit in the month in ANY currency (unique index is per student+month)
  EXISTS (SELECT 1 FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
            AND t.is_auto_charge)                                            AS any_auto_charge_row,
  EXISTS (SELECT 1 FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
            AND t.is_auto_credit)                                            AS any_auto_credit_row,
  -- adjacent months (evidence for amount / rank)
  pc.amount AS prev_charge_amount, pc.currency AS prev_charge_currency,
  nc.amount AS next_charge_amount, nc.currency AS next_charge_currency,
  pcr.amount AS prev_credit_amount, ncr.amount AS next_credit_amount,
  (SELECT count(*) FROM recon_tx t WHERE t.student_id = r.student_id AND t.is_auto_credit AND t.is_active)
                                                                             AS auto_credits_ever,
  (SELECT count(*) FROM recon_tx t WHERE t.student_id = r.student_id AND t.is_auto_credit AND t.is_active
     AND NOT (pe.cur_rank = ANY (p.auto_ranks)))                            AS auto_credits_with_unapproved_rank,
  -- manual activity, this month & currency
  coalesce(md.n, 0) AS manual_debit_count,  md.total AS manual_debit_total,  md.detail AS manual_debit_detail,
  coalesce(mc.n, 0) AS manual_credit_count, mc.total AS manual_credit_total, mc.detail AS manual_credit_detail,
  -- manual activity in the same month but ANOTHER currency (never netted, only flagged)
  (SELECT count(*) FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
     AND t.is_active AND (t.is_manual_debit OR t.is_manual_credit) AND t.currency IS DISTINCT FROM r.currency)
                                                                             AS manual_other_currency_count,
  -- manual debits/credits recorded under ANOTHER month, created after this month's charge/credit date
  od.n AS late_manual_debit_count, od.detail AS late_manual_debit_detail,
  oc.n AS late_manual_credit_count, oc.detail AS late_manual_credit_detail,
  (SELECT count(*) FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
     AND t.is_active AND t.is_unknown_type)                                  AS unknown_type_count,
  coalesce((SELECT sum(t.amount) FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
     AND t.currency IS NOT DISTINCT FROM r.currency AND t.is_active), 0)    AS net_existing,
  (SELECT string_agg(t.transaction_type || ':' || t.amount::text || ' ' || t.currency ||
            ' @' || t.transaction_date::text || ' נוצר ' || to_char(t.created_at, 'YYYY-MM-DD') ||
            coalesce(' "' || left(t.note, 60) || '"', '') ||
            CASE WHEN t.is_active THEN '' ELSE ' [מבוטל]' END, ' | ' ORDER BY t.created_at)
     FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
       AND t.currency IS NOT DISTINCT FROM r.currency)                      AS all_tx_detail
FROM recon_rows r
CROSS JOIN recon_params p
LEFT JOIN recon_people pe ON pe.student_id = r.student_id
LEFT JOIN LATERAL (
  SELECT min(t.id::text)::uuid AS id, min(t.amount) AS amount, count(*) AS n
  FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
    AND t.currency IS NOT DISTINCT FROM r.currency AND t.is_auto_charge AND t.is_active
) ac ON true
LEFT JOIN LATERAL (
  SELECT max(t.amount) AS amount, count(*) AS n
  FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
    AND t.currency IS NOT DISTINCT FROM r.currency AND t.is_auto_credit AND t.is_active
) acr ON true
LEFT JOIN LATERAL (
  SELECT t.amount, t.currency FROM recon_tx t WHERE t.student_id = r.student_id
    AND t.billing_month = (r.month - interval '1 month')::date AND t.is_auto_charge AND t.is_active LIMIT 1
) pc ON true
LEFT JOIN LATERAL (
  SELECT t.amount, t.currency FROM recon_tx t WHERE t.student_id = r.student_id
    AND t.billing_month = (r.month + interval '1 month')::date AND t.is_auto_charge AND t.is_active LIMIT 1
) nc ON true
LEFT JOIN LATERAL (
  SELECT t.amount FROM recon_tx t WHERE t.student_id = r.student_id
    AND t.billing_month = (r.month - interval '1 month')::date AND t.is_auto_credit AND t.is_active LIMIT 1
) pcr ON true
LEFT JOIN LATERAL (
  SELECT t.amount FROM recon_tx t WHERE t.student_id = r.student_id
    AND t.billing_month = (r.month + interval '1 month')::date AND t.is_auto_credit AND t.is_active LIMIT 1
) ncr ON true
LEFT JOIN LATERAL (
  SELECT count(*) AS n, sum(t.amount) AS total,
         string_agg(t.transaction_type || ' ' || t.amount::text || coalesce(' "' || left(t.note, 60) || '"', ''), ' | ') AS detail
  FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
    AND t.currency IS NOT DISTINCT FROM r.currency AND t.is_active AND t.is_manual_debit
) md ON true
LEFT JOIN LATERAL (
  SELECT count(*) AS n, sum(t.amount) AS total,
         string_agg(t.transaction_type || ' ' || t.amount::text || coalesce(' "' || left(t.note, 60) || '"', ''), ' | ') AS detail
  FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month = r.month
    AND t.currency IS NOT DISTINCT FROM r.currency AND t.is_active AND t.is_manual_credit
) mc ON true
LEFT JOIN LATERAL (
  SELECT count(*) AS n,
         string_agg(t.transaction_type || ' ' || t.amount::text || ' ' || t.currency || ' לחודש ' || t.billing_month::text ||
                    ' נוצר ' || to_char(t.created_at, 'YYYY-MM-DD') || coalesce(' "' || left(t.note, 60) || '"', ''), ' | ') AS detail
  FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month <> r.month
    AND t.is_active AND t.is_manual_debit
    AND t.created_at >= (r.month + 19)::timestamp      -- on/after the 20th of the month in question
) od ON true
LEFT JOIN LATERAL (
  SELECT count(*) AS n,
         string_agg(t.transaction_type || ' ' || t.amount::text || ' ' || t.currency || ' לחודש ' || t.billing_month::text ||
                    ' נוצר ' || to_char(t.created_at, 'YYYY-MM-DD') || coalesce(' "' || left(t.note, 60) || '"', ''), ' | ') AS detail
  FROM recon_tx t WHERE t.student_id = r.student_id AND t.billing_month <> r.month
    AND t.is_active AND t.is_manual_credit
    AND t.created_at >= (r.month + 20)::timestamp      -- on/after the 21st
) oc ON true;

-- ── decisions ───────────────────────────────────────────────────────────────
CREATE TEMP TABLE recon_result AS
WITH d AS (
  SELECT f.*,
    -- amount evidence from an adjacent automatic charge that equals CURRENT tuition & currency
    (f.prev_charge_amount = -f.cur_amount AND f.prev_charge_currency = f.cur_currency
       AND f.cur_currency = f.currency)                                     AS ev_prev,
    (f.next_charge_amount = -f.cur_amount AND f.next_charge_currency = f.cur_currency
       AND f.cur_currency = f.currency)                                     AS ev_next,
    (f.start_date IS NOT NULL AND date_trunc('month', f.start_date)::date > f.month) AS not_yet_billable
  FROM recon_facts f
),
charge AS (
  SELECT d.*,
    CASE
      WHEN NOT d.is_expected_currency                    THEN 'other_currency'
      WHEN d.auto_charge_count >= 1                      THEN 'present'
      WHEN d.auto_charge_cancelled OR d.any_auto_charge_row THEN 'cancelled_or_other'
      WHEN d.not_yet_billable                            THEN 'not_billable'
      ELSE 'missing'
    END AS charge_state
  FROM d
),
charge_reasons AS (
  SELECT c.*,
    array_remove(ARRAY[
      CASE WHEN c.person_kind IS NULL THEN 'ORPHAN: אין תלמיד/בוגר עם המזהה' END,
      CASE WHEN c.currency IS NULL THEN 'NO_CURRENCY: מטבע צפוי לא ידוע' END,
      CASE WHEN c.charge_state = 'other_currency' AND c.net_existing <> 0
           THEN 'FOREIGN_CURRENCY_TX: תנועות במטבע שאינו המטבע הצפוי — לא מתקזזות' END,
      CASE WHEN c.auto_charge_count > 1 THEN 'DUPLICATE_AUTO_CHARGE: יותר מחיוב אוטומטי פעיל אחד' END,
      CASE WHEN c.auto_credit_count > 1 THEN 'DUPLICATE_AUTO_CREDIT: יותר מזיכוי אוטומטי פעיל אחד' END,
      CASE WHEN c.unknown_type_count > 0 THEN 'UNKNOWN_TX_TYPE: סוג תנועה לא מוכר' END,
      CASE WHEN c.manual_other_currency_count > 0
           THEN 'MANUAL_OTHER_CURRENCY: תנועה ידנית באותו חודש במטבע אחר' END,
      -- existing state anomalies
      CASE WHEN c.charge_state = 'present' AND c.manual_debit_count > 0
           THEN 'POSSIBLE_DOUBLE_CHARGE: קיים חיוב אוטומטי וגם חיוב ידני/התאמה שלילית באותו חודש' END,
      CASE WHEN c.charge_state = 'present' AND c.not_yet_billable
           THEN 'CHARGE_BEFORE_START: חיוב קיים לפני תאריך תחילת הגבייה הנוכחי' END,
      CASE WHEN c.auto_credit_count >= 1 AND NOT coalesce(c.rank_approved_now, false)
           THEN 'CREDIT_RANK_NOT_APPROVED: זיכוי אוטומטי קיים אך הדירוג הנוכחי (' || coalesce(c.cur_rank, '—') || ') אינו מזכה' END,
      CASE WHEN c.auto_credit_count >= 1 AND c.auto_charge_count >= 1 AND c.auto_credit_amount <> -c.auto_charge_amount
           THEN 'CREDIT_CHARGE_MISMATCH: סכום הזיכוי שונה מהחיוב' END,
      CASE WHEN c.auto_credit_count >= 1 AND c.auto_charge_count = 0
           THEN 'CREDIT_WITHOUT_CHARGE: זיכוי אוטומטי ללא חיוב אוטומטי פעיל' END,
      -- missing-charge blockers
      CASE WHEN c.charge_state = 'missing' AND c.person_kind = 'alumni'
           THEN 'GRADUATED: התלמיד עבר לבוגרים — לבדוק מועד יציאה' END,
      CASE WHEN c.charge_state = 'missing' AND (coalesce(c.cur_amount, 0) <= 0 OR c.cur_currency NOT IN ('ILS','USD') OR c.cur_currency IS NULL)
           THEN 'NO_VALID_CURRENT_TUITION: אין סכום/מטבע תקינים כיום (שכ"ל="' || coalesce(c.cur_tuition_raw, '') || '")' END,
      CASE WHEN c.charge_state = 'missing' AND c.prev_charge_amount IS NULL AND c.next_charge_amount IS NOT NULL
           THEN 'NO_PRIOR_MONTH_CHARGE: אין חיוב בחודש הקודם (יש רק בחודש הבא' ||
                CASE WHEN coalesce(c.ev_next, false) THEN ', בסכום זהה' ELSE ', בסכום שונה' END ||
                ') — לא ידוע אם התלמיד היה בגבייה באותו חודש' END,
      CASE WHEN c.charge_state = 'missing' AND c.prev_charge_amount IS NOT NULL AND NOT coalesce(c.ev_prev, false)
           THEN 'AMOUNT_CHANGED: סכום/מטבע החיוב בחודש סמוך שונה מהנוכחי (' ||
                coalesce(c.prev_charge_amount::text || ' ' || c.prev_charge_currency, '—') || ' / ' ||
                coalesce(c.next_charge_amount::text || ' ' || c.next_charge_currency, '—') || ' מול ' ||
                coalesce(c.cur_tuition_raw, '—') || ' ' || coalesce(c.cur_currency, '—') || ')' END,
      CASE WHEN c.charge_state = 'missing' AND c.prev_charge_amount IS NULL AND c.next_charge_amount IS NULL
           THEN 'NO_HISTORICAL_EVIDENCE: אין חיוב אוטומטי בחודש סמוך — רק ערכים נוכחיים' END,
      CASE WHEN c.charge_state = 'missing' AND c.manual_debit_count > 0
           THEN 'MANUAL_CHARGE_SAME_MONTH: חיוב ידני/התאמה באותו חודש — ייתכן שמחליף את החיוב החסר (' || c.manual_debit_detail || ')' END,
      CASE WHEN c.charge_state = 'missing' AND coalesce(c.late_manual_debit_count, 0) > 0
           THEN 'LATE_MANUAL_CHARGE_OTHER_MONTH: חיוב ידני שנרשם לחודש אחר אחרי מועד החיוב החסר (' || c.late_manual_debit_detail || ')' END
    ], NULL) AS charge_b_reasons
  FROM charge c
),
credit AS (
  SELECT cr.*,
    CASE
      WHEN cr.charge_state = 'other_currency'                     THEN 'n/a'
      WHEN cr.auto_credit_count >= 1                              THEN 'present'
      WHEN cr.auto_credit_cancelled OR cr.any_auto_credit_row     THEN 'cancelled_or_other'
      WHEN cr.charge_state IN ('not_billable', 'cancelled_or_other') THEN 'n/a'
      WHEN NOT coalesce(cr.rank_approved_now, false) AND cr.auto_credits_ever = 0 THEN 'not_needed'
      ELSE 'missing'
    END AS credit_state
  FROM charge_reasons cr
),
credit_reasons AS (
  SELECT c.*,
    array_remove(ARRAY[
      CASE WHEN c.credit_state = 'missing' AND NOT coalesce(c.rank_approved_now, false)
           THEN 'RANK_CHANGED: היו זיכויים אוטומטיים אך הדירוג הנוכחי (' || coalesce(c.cur_rank, '—') || ') אינו מזכה' END,
      CASE WHEN c.credit_state = 'missing' AND coalesce(c.rank_approved_now, false)
                AND c.prev_credit_amount IS NULL
                AND c.cur_rank IN ('קירוב לבבות', 'מרכז הצדקה')
           THEN 'RANK_NOT_IN_OLD_FUNCTION: דירוג "' || c.cur_rank || '" לא זוכה ע"י הפונקציה הישנה — אין ראיה היסטורית לדירוג' END,
      CASE WHEN c.credit_state = 'missing' AND coalesce(c.rank_approved_now, false)
                AND c.prev_credit_amount IS NULL
                AND c.cur_rank NOT IN ('קירוב לבבות', 'מרכז הצדקה')
           THEN 'NO_RANK_EVIDENCE: הדירוג הנוכחי מזכה אך אין זיכוי אוטומטי בחודש הקודם' ||
                CASE WHEN c.next_credit_amount IS NOT NULL THEN ' (יש בחודש הבא)' ELSE '' END END,
      CASE WHEN c.credit_state = 'missing' AND c.prev_credit_amount IS NOT NULL
                AND c.prev_credit_amount <> -coalesce(c.auto_charge_amount, -c.cur_amount)
           THEN 'CREDIT_AMOUNT_CHANGED: זיכוי החודש הקודם (' || c.prev_credit_amount::text || ') שונה מהחיוב' END,
      CASE WHEN c.credit_state = 'missing' AND c.manual_credit_count > 0
           THEN 'MANUAL_PAYMENT_SAME_MONTH: תשלום ידני/התאמה חיובית באותו חודש — ייתכן שכבר מכסה (' || c.manual_credit_detail || ')' END,
      CASE WHEN c.credit_state = 'missing' AND coalesce(c.late_manual_credit_count, 0) > 0
           THEN 'LATE_MANUAL_PAYMENT_OTHER_MONTH: תשלום ידני שנרשם לחודש אחר אחרי מועד הזיכוי החסר (' || c.late_manual_credit_detail || ')' END,
      CASE WHEN c.credit_state = 'missing' AND c.charge_state = 'present'
                AND c.auto_charge_amount <> -c.cur_amount
           THEN 'CREDIT_AMOUNT_VS_CURRENT: הזיכוי ישוקף מהחיוב הקיים (' || c.auto_charge_amount::text || ') השונה מהסכום הנוכחי' END
    ], NULL) AS credit_b_reasons
  FROM credit c
)
SELECT
  x.student_id, x.person_kind, x.name, x.class_name, x.passport_or_id,
  x.month, x.currency,
  x.cur_tuition_raw, x.cur_currency, x.cur_rank, x.start_date, x.updated_at,
  -- what the charge SHOULD be and why
  CASE
    WHEN x.charge_state = 'present' THEN x.auto_charge_amount
    WHEN x.charge_state = 'missing' AND x.ev_prev THEN -x.cur_amount
  END AS expected_charge,
  -- indicative only (current tuition) — for sizing category-B cases, never used for writing
  CASE WHEN x.charge_state = 'missing' THEN -x.cur_amount END AS indicative_charge,
  CASE
    WHEN x.charge_state = 'present' THEN 'חיוב אוטומטי קיים'
    WHEN x.charge_state = 'missing' AND x.ev_prev AND x.ev_next THEN 'חיוב אוטומטי זהה בחודש הקודם ובחודש הבא'
    WHEN x.charge_state = 'missing' AND x.ev_prev THEN 'חיוב אוטומטי זהה בחודש הקודם (' || x.prev_charge_amount::text || ' ' || x.prev_charge_currency || ')'
    WHEN x.charge_state = 'missing' THEN 'אין ראיה מספקת — סכום נוכחי בלבד (אינדיקטיבי)'
    WHEN x.charge_state = 'not_billable' THEN 'לפני תאריך תחילת גבייה ' || x.start_date::text
    WHEN x.charge_state = 'cancelled_or_other' THEN 'חיוב אוטומטי בוטל ידנית / קיים במטבע אחר'
  END AS amount_evidence,
  CASE
    WHEN x.auto_credits_ever > 0 AND x.rank_approved_now THEN 'מזכה (דירוג נוכחי + זיכויים קודמים)'
    WHEN x.rank_approved_now THEN 'מזכה לפי דירוג נוכחי בלבד — היסטוריה לא ידועה'
    WHEN x.auto_credits_ever > 0 THEN 'לא מזכה כיום, אך זוכה בעבר'
    ELSE 'לא מזכה'
  END AS historical_rank_evidence,
  x.charge_state, x.credit_state,
  x.auto_charge_amount   AS existing_auto_charge,
  x.auto_credit_amount   AS existing_auto_credit,
  x.manual_debit_total   AS manual_charges,
  x.manual_credit_total  AS manual_payments_and_credits,
  x.manual_debit_detail, x.manual_credit_detail,
  x.late_manual_debit_detail, x.late_manual_credit_detail,
  x.net_existing,
  -- decisions
  (x.charge_state = 'missing')                                                 AS charge_missing,
  (x.credit_state = 'missing')                                                 AS credit_missing,
  (x.charge_b_reasons || x.credit_b_reasons) AS b_reasons,
  CASE
    WHEN cardinality(x.charge_b_reasons || x.credit_b_reasons) > 0 THEN 'B'
    WHEN x.charge_state = 'missing' OR x.credit_state = 'missing'  THEN 'A'
    ELSE 'C'
  END AS category,
  (cardinality(x.charge_b_reasons || x.credit_b_reasons) = 0
     AND (x.charge_state = 'missing' OR x.credit_state = 'missing'))        AS safe_auto_recovery,
  (cardinality(x.charge_b_reasons || x.credit_b_reasons) > 0)              AS needs_human,
  (x.charge_state = 'present' AND x.manual_debit_count > 0) OR x.auto_charge_count > 1 AS suspected_duplicate,
  x.all_tx_detail
FROM credit_reasons x;

-- ── recovery plan: ONLY category A ─────────────────────────────────────────
-- Charge: amount = -current tuition (proven equal to an adjacent automatic charge),
--         transaction_date = 20th. Credit: mirrors the charge, transaction_date = 21st.
CREATE TEMP TABLE recon_plan AS
SELECT
  r.student_id, r.name, r.month AS billing_month, (r.month + 19) AS transaction_date,
  r.expected_charge AS amount, r.currency, 'monthly_charge'::text AS transaction_type,
  'חיוב: ' || r.amount_evidence AS evidence
FROM recon_result r
WHERE r.category = 'A' AND r.charge_missing
UNION ALL
SELECT
  r.student_id, r.name, r.month, (r.month + 20),
  -coalesce(r.existing_auto_charge, r.expected_charge), r.currency, 'automatic_payment',
  'זיכוי: דירוג ' || r.cur_rank || ' מזכה; ' || r.historical_rank_evidence ||
  '; סכום משוקף מהחיוב ' || CASE WHEN r.charge_missing THEN 'המשוחזר' ELSE 'הקיים' END
FROM recon_result r
WHERE r.category = 'A' AND r.credit_missing;

-- Safety net: a plan row must never have NULL/zero amount or currency.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM recon_plan WHERE amount IS NULL OR amount = 0 OR currency NOT IN ('ILS','USD') OR currency IS NULL) THEN
    RAISE EXCEPTION 'recon_plan contains invalid rows — aborting';
  END IF;
  IF EXISTS (SELECT 1 FROM recon_plan WHERE transaction_type = 'monthly_charge' AND amount > 0)
     OR EXISTS (SELECT 1 FROM recon_plan WHERE transaction_type = 'automatic_payment' AND amount < 0) THEN
    RAISE EXCEPTION 'recon_plan sign error — aborting';
  END IF;
END $$;

-- ── start-date restore proposal ─────────────────────────────────────────────
-- Paying students with NULL start date. Their billing month only needs the
-- start MONTH; we propose the 20th of the first month they were charged.
--   first automatic charge in 2026-08  → 2026-08-20 (matches the client's deliberate reset) → A
--   first automatic charge later       → 20th of that month → B (human confirms)
--   never charged                      → B, no proposal
CREATE TEMP TABLE recon_start_date AS
SELECT
  pe.student_id, pe.name, pe.class_name, pe.passport_or_id,
  pe.cur_tuition_raw, pe.cur_currency, pe.cur_rank, pe.updated_at,
  fc.first_month AS first_auto_charge_month,
  fc.last_month  AS last_auto_charge_month,
  CASE WHEN fc.first_month IS NOT NULL THEN fc.first_month + 19 END AS proposed_start_date,
  CASE
    WHEN fc.first_month = date '2026-08-01' THEN 'A'
    ELSE 'B'
  END AS category,
  CASE
    WHEN fc.first_month = date '2026-08-01'
      THEN 'חויב אוטומטית מאוגוסט 2026 — תואם לאיפוס המכוון ל-20.08.2026'
    WHEN fc.first_month IS NOT NULL
      THEN 'חיוב אוטומטי ראשון ב-' || fc.first_month::text || ' — לאשר תאריך'
    ELSE 'לא חויב מעולם — אין ראיה לתאריך'
  END AS evidence
FROM recon_people pe
LEFT JOIN LATERAL (
  SELECT min(t.billing_month) AS first_month, max(t.billing_month) AS last_month
  FROM recon_tx t WHERE t.student_id = pe.student_id AND t.is_auto_charge AND t.is_active
) fc ON true
WHERE pe.person_kind = 'student'
  AND pe.start_date IS NULL
  AND pe.cur_amount > 0
  AND pe.cur_currency IN ('ILS', 'USD');

-- ════════════════════════════════════════════════════════════
-- END OF CORE
-- ════════════════════════════════════════════════════════════

-- ── SUMMARY: counts and amounts, never mixing currencies ──
WITH base AS (SELECT * FROM recon_result)
SELECT 'א. שורות לפי קטגוריה' AS section, month::text AS month, coalesce(currency, '—') AS currency,
       category AS key, count(*) AS rows, NULL::numeric AS amount
FROM base GROUP BY month, currency, category
UNION ALL
SELECT 'ב. חיובים חסרים — A (לשחזור)', month::text, currency, 'monthly_charge', count(*), sum(expected_charge)
FROM base WHERE category = 'A' AND charge_missing GROUP BY month, currency
UNION ALL
SELECT 'ג. זיכויים חסרים — A (לשחזור)', month::text, currency, 'automatic_payment', count(*),
       sum(-coalesce(existing_auto_charge, expected_charge))
FROM base WHERE category = 'A' AND credit_missing GROUP BY month, currency
UNION ALL
SELECT 'ד. חיובים חסרים לכאורה — B (בדיקה, סכום אינדיקטיבי נוכחי)', month::text, coalesce(currency, '—'), 'monthly_charge', count(*), sum(indicative_charge)
FROM base WHERE category = 'B' AND charge_missing GROUP BY month, currency
UNION ALL
SELECT 'ה. זיכויים חסרים לכאורה — B (בדיקה, סכום אינדיקטיבי)', month::text, coalesce(currency, '—'), 'automatic_payment', count(*),
       sum(-coalesce(existing_auto_charge, indicative_charge))
FROM base WHERE category = 'B' AND credit_missing GROUP BY month, currency
UNION ALL
SELECT 'ו. סיבות B', month::text, coalesce(currency, '—'), split_part(reason, ':', 1), count(*), NULL
FROM base, unnest(b_reasons) AS reason GROUP BY month, currency, split_part(reason, ':', 1)
UNION ALL
SELECT 'ז. חשד לכפילות קיימת', month::text, coalesce(currency, '—'), 'suspected_duplicate', count(*), NULL
FROM base WHERE suspected_duplicate GROUP BY month, currency
UNION ALL
SELECT 'ח. תאריך התחלה חסר', NULL, coalesce(cur_currency, '—'), 'start_date_' || category, count(*), NULL
FROM recon_start_date GROUP BY cur_currency, category
UNION ALL
SELECT 'ט. סה"כ תנועות במערכת (פעילות)', billing_month::text, currency, transaction_type, count(*), sum(amount)
FROM recon_tx, recon_params p
WHERE is_active AND billing_month BETWEEN p.from_month AND p.to_month
GROUP BY billing_month, currency, transaction_type
ORDER BY 1, 2, 3, 4;
